  'adf8b12615c26e9aad1b2f1fb73fc48d2033492449f1d275885a12569fa5ecb6',
  $free_spi_sample${"questionBank":{"schemaVersion":1,"version":1,"vocabularyCatalog":{"version":1,"terms":{}},"questions":[{"id":"spi-free-nv-order-01","version":1,"testFamily":"spi","domain":"nonverbal","category":"conditions-and-ordering","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"foundation","targetSeconds":90,"promptJa":"P、Q、R、S の4人が徒競走をした。同着はいなかった。次のことがわかっている。\nア　P は Q より先にゴールした。\nイ　R は S より後にゴールしたが、Q より先にゴールした。\n1位になった可能性があるのは誰か。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"P だけ"},{"id":"b","textJa":"S だけ"},{"id":"c","textJa":"P と S"},{"id":"d","textJa":"P と R"},{"id":"e","textJa":"P と R と S"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"c"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"イより S → R → Q の順、アより P → Q の順。Q は P と R の両方より後なので4位に決まる。残る P・S・R のうち、R は S より後なので1位になれない。1位の可能性があるのは P と S。","whatIsAskedJa":"前後関係の条件を整理し、「1位になる可能性がある人」をすべて選ぶ問題です。順位が一通りに決まらなくても、条件に反しない並び方が一つでもあれば「可能性がある」と判断します。","representation":{"kind":"elimination","candidates":["P","Q","R","S"],"steps":["Q：P と R より後 → 4位に確定","R：S より後 → 1位にはなれない","P・S：先頭に置いても条件に反しない → 可能性あり"]}},"itemAnalysis":{"languageLoads":["condition-parsing"],"reasoningLoads":["constraint-reasoning"],"executionLoads":["choice-elimination"]}},{"id":"spi-free-nv-order-02","version":1,"testFamily":"spi","domain":"nonverbal","category":"conditions-and-ordering","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":90,"promptJa":"A、B、C、D、E の5人の年齢について、次のことがわかっている。同じ年齢の人はいない。\nア　A は B より年上で、C より年下である。\nイ　D は C より年上である。\nウ　E は B より年下である。\n確実にいえることはどれか。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"最も年上なのは C である"},{"id":"b","textJa":"A は年上から数えて3番目である"},{"id":"c","textJa":"最も年下なのは B である"},{"id":"d","textJa":"D と E の間には2人いる"},{"id":"e","textJa":"C は B より年下である"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"b"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"アより C ＞ A ＞ B、イより D ＞ C、ウより B ＞ E。つなげると D ＞ C ＞ A ＞ B ＞ E となり、全員の順番が決まる。A は年上から3番目。","whatIsAskedJa":"複数の大小関係を一本の順番につなげ、選択肢のうち必ず正しいものを選ぶ問題です。「確実にいえる」は、条件からどの場合でも成り立つことを意味します。","representation":{"kind":"equation","expression":"D ＞ C ＞ A ＞ B ＞ E"}},"itemAnalysis":{"languageLoads":["condition-parsing"],"reasoningLoads":["constraint-reasoning"],"executionLoads":["choice-elimination"]}},{"id":"spi-free-nv-profit-01","version":1,"testFamily":"spi","domain":"nonverbal","category":"percentage-profit-loss","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"foundation","targetSeconds":90,"promptJa":"原価 800 円の商品に、原価の 25% の利益を見込んで定価をつけた。売れなかったので、定価の1割引きで売った。このときの利益はいくらか。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"50 円"},{"id":"b","textJa":"80 円"},{"id":"c","textJa":"100 円"},{"id":"d","textJa":"120 円"},{"id":"e","textJa":"200 円"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"c"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"定価＝800 ×（1＋0.25）＝1000 円。売値＝1000 ×（1−0.1）＝900 円。利益＝売値−原価＝900−800＝100 円。","whatIsAskedJa":"「原価に対して 25%」と「定価から1割引き」は基準になる金額が違います。基準を取り違えずに売値を求め、最後に売値から原価を引いて利益を出す問題です。","representation":{"kind":"equation","expression":"800 × 1.25 × 0.9 − 800 ＝ 100"}},"itemAnalysis":{"languageLoads":["condition-parsing"],"reasoningLoads":["quantitative-reasoning"],"executionLoads":["calculation"]}},{"id":"spi-free-nv-profit-02","version":1,"testFamily":"spi","domain":"nonverbal","category":"percentage-profit-loss","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":60,"promptJa":"ある会社の今年の社員数は 360 人で、昨年より 20% 増えた。昨年の社員数は何人か。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"280 人"},{"id":"b","textJa":"288 人"},{"id":"c","textJa":"300 人"},{"id":"d","textJa":"320 人"},{"id":"e","textJa":"340 人"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"c"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"昨年の人数を x とすると、x ×（1＋0.2）＝360 なので x＝360 ÷ 1.2＝300 人。360 から 360 の 20% を引いた 288 人は誤り。","whatIsAskedJa":"増加率の基準は「今年」ではなく「昨年」です。基準を未知数にして式を立て、逆算できるかを確かめる問題です。","representation":{"kind":"equation","expression":"x × 1.2 ＝ 360　→　x ＝ 300"}},"itemAnalysis":{"languageLoads":["condition-parsing"],"reasoningLoads":["model-selection","quantitative-reasoning"],"executionLoads":["calculation"]}},{"id":"spi-free-nv-rate-01","version":1,"testFamily":"spi","domain":"nonverbal","category":"rate-and-work","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"foundation","targetSeconds":60,"promptJa":"家から駅まで、分速 80m で歩くと 15 分かかる。同じ道を分速 200m の自転車で行くと、何分かかるか。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"5 分"},{"id":"b","textJa":"6 分"},{"id":"c","textJa":"7 分 30 秒"},{"id":"d","textJa":"8 分"},{"id":"e","textJa":"10 分"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"b"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"道のり＝速さ × 時間＝80 × 15＝1200m。自転車では 1200 ÷ 200＝6 分。","whatIsAskedJa":"変わらないのは「道のり」です。まず道のりを求め、別の速さで割って時間を出す問題です。","representation":{"kind":"equation","expression":"80 × 15 ＝ 1200　→　1200 ÷ 200 ＝ 6"}},"itemAnalysis":{"languageLoads":[],"reasoningLoads":["quantitative-reasoning"],"executionLoads":["calculation"]}},{"id":"spi-free-nv-rate-02","version":1,"testFamily":"spi","domain":"nonverbal","category":"rate-and-work","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":90,"promptJa":"ある作業を、A は1人で6時間、B は1人で 12 時間で終える。2人で一緒に作業すると、何時間で終わるか。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"3 時間"},{"id":"b","textJa":"4 時間"},{"id":"c","textJa":"4 時間 30 分"},{"id":"d","textJa":"6 時間"},{"id":"e","textJa":"9 時間"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"b"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"全体の仕事量を 6 と 12 の最小公倍数の 12 とおく。A は1時間に 2、B は1時間に 1 進めるので、2人で1時間に 3。12 ÷ 3＝4 時間。","whatIsAskedJa":"仕事算では「全体の量」を扱いやすい数におくと計算が簡単になります。それぞれの1時間あたりの仕事量を足し、全体を割る問題です。","representation":{"kind":"table","columns":["担当","1時間あたり","全体（12）を終える時間"],"rows":[["A","2","6 時間"],["B","1","12 時間"],["A＋B","3","4 時間"]]}},"itemAnalysis":{"languageLoads":[],"reasoningLoads":["model-selection","quantitative-reasoning"],"executionLoads":["calculation"]}},{"id":"spi-free-nv-sets-01","version":1,"testFamily":"spi","domain":"nonverbal","category":"sets-and-counting","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"foundation","targetSeconds":90,"promptJa":"ある会社の社員 100 人に調査したところ、英語を話せる人は 62 人、中国語を話せる人は 25 人、どちらも話せない人は 28 人だった。英語と中国語の両方を話せる人は何人か。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"10 人"},{"id":"b","textJa":"13 人"},{"id":"c","textJa":"15 人"},{"id":"d","textJa":"18 人"},{"id":"e","textJa":"25 人"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"c"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"少なくとも一方を話せる人は 100−28＝72 人。英語と中国語の人数を足すと 62＋25＝87 人で、両方話せる人を二重に数えている。両方話せる人は 87−72＝15 人。","whatIsAskedJa":"2つの集合の重なりを求める問題です。「どちらも話せない人」から「少なくとも一方を話せる人」を出し、足し算で二重に数えた分を引きます。","representation":{"kind":"table","columns":["区分","中国語○","中国語×","計"],"rows":[["英語○","15","47","62"],["英語×","10","28","38"],["計","25","75","100"]]}},"itemAnalysis":{"languageLoads":["condition-parsing"],"reasoningLoads":["model-selection"],"executionLoads":["calculation"]}},{"id":"spi-free-nv-sets-02","version":1,"testFamily":"spi","domain":"nonverbal","category":"sets-and-counting","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":60,"promptJa":"赤・青・黄・緑の4色から異なる2色を選び、ポスターの文字色と背景色にする。文字色と背景色の組み合わせは何通りあるか。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"6 通り"},{"id":"b","textJa":"8 通り"},{"id":"c","textJa":"12 通り"},{"id":"d","textJa":"16 通り"},{"id":"e","textJa":"24 通り"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"c"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"文字色の選び方が4通り、残りから背景色の選び方が3通りなので 4 × 3＝12 通り。「赤の文字に青の背景」と「青の文字に赤の背景」は別のポスターになる。","whatIsAskedJa":"選んだ2色に「文字色」「背景色」という役割の違いがあるかどうかで、順列か組み合わせかを判断する問題です。役割が違うので順番を区別します（6 通りは組み合わせとして数えた誤り）。"},"itemAnalysis":{"languageLoads":["condition-parsing"],"reasoningLoads":["model-selection"],"executionLoads":["calculation"]}},{"id":"spi-free-v-relation-01","version":1,"testFamily":"spi","domain":"verbal","category":"semantic-relation","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"foundation","targetSeconds":45,"promptJa":"最初に示された二語の関係を考え、同じ関係のものを選びなさい。\n医師：診察\nア　教師：授業\nイ　はさみ：切断\nウ　記者：取材","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"アだけ"},{"id":"b","textJa":"イだけ"},{"id":"c","textJa":"ウだけ"},{"id":"d","textJa":"アとイ"},{"id":"e","textJa":"アとウ"},{"id":"f","textJa":"イとウ"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"e"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"「医師：診察」は「人：その人が行う仕事」の関係。教師は授業を、記者は取材を行うので同じ関係。はさみは人ではなく道具で、「道具：用途」の関係になる。","whatIsAskedJa":"二語の関係（仕事・用途・包含・原料など）を一言で言い表し、選択肢の二語にも同じ言い方が当てはまるかを確かめる問題です。"},"itemAnalysis":{"languageLoads":["semantic-relation"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-relation-02","version":1,"testFamily":"spi","domain":"verbal","category":"semantic-relation","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":45,"promptJa":"最初に示された二語の関係を考え、同じ関係のものを選びなさい。\n鉛筆：文房具\nア　柔道：武道\nイ　机：家具\nウ　屋根：家","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"アだけ"},{"id":"b","textJa":"イだけ"},{"id":"c","textJa":"ウだけ"},{"id":"d","textJa":"アとイ"},{"id":"e","textJa":"アとウ"},{"id":"f","textJa":"イとウ"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"d"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"「鉛筆は文房具の一種」という包含の関係。柔道は武道の一種、机は家具の一種なので同じ関係。屋根は家の一部であり、「部分：全体」の関係なので異なる。","whatIsAskedJa":"「A は B の一種」（包含）と「A は B の一部」（部分と全体）を区別できるかを問う問題です。"},"itemAnalysis":{"languageLoads":["semantic-relation"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-vocab-01","version":1,"testFamily":"spi","domain":"verbal","category":"vocabulary-in-context","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":45,"promptJa":"次の意味を表す語として、最も適切なものを選びなさい。\n「計画や事業が途中で行き詰まり、先へ進まなくなること」","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"頓挫"},{"id":"b","textJa":"逡巡"},{"id":"c","textJa":"斟酌"},{"id":"d","textJa":"杞憂"},{"id":"e","textJa":"踏襲"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"a"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"頓挫（とんざ）は、計画や事業が途中で行き詰まること。逡巡＝決断できずにためらうこと、斟酌＝事情をくみ取って手加減すること、杞憂＝しなくてよい心配、踏襲＝前のやり方をそのまま受け継ぐこと。","whatIsAskedJa":"ビジネス文書や報道でよく使われる漢語の意味を正確に区別する問題です。「計画が頓挫する」のように、一緒に使われる語と合わせて覚えると定着しやすくなります。"},"itemAnalysis":{"languageLoads":["vocabulary"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-vocab-02","version":1,"testFamily":"spi","domain":"verbal","category":"vocabulary-in-context","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":45,"promptJa":"文中の空欄に入る語として、最も適切なものを選びなさい。\n「先方の事情を〔　　〕し、納期を一週間延ばすことにした。」","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"斟酌"},{"id":"b","textJa":"看過"},{"id":"c","textJa":"遵守"},{"id":"d","textJa":"踏襲"},{"id":"e","textJa":"拘泥"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"a"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"「斟酌（しんしゃく）する」は、相手の事情をくみ取って配慮すること。事情に配慮して納期を延ばすという文脈に合う。看過＝見過ごすこと、遵守＝規則などを守ること、踏襲＝前例をそのまま受け継ぐこと、拘泥＝必要以上にこだわること。","whatIsAskedJa":"空欄の前後（「先方の事情を」「納期を延ばす」）から、どのような行為が入るかを判断し、意味と用法が合う語を選ぶ問題です。"},"itemAnalysis":{"languageLoads":["vocabulary","reading-comprehension"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-logic-01","version":1,"testFamily":"spi","domain":"verbal","category":"sentence-logic","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"foundation","targetSeconds":45,"promptJa":"空欄に入る語として、最も適切なものを選びなさい。\n「新サービスの利用者数は順調に伸びている。〔　　〕、一人当たりの利用時間は減少傾向にあり、収益への貢献はまだ限定的だ。」","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"しかし"},{"id":"b","textJa":"したがって"},{"id":"c","textJa":"つまり"},{"id":"d","textJa":"たとえば"},{"id":"e","textJa":"そのうえ"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"a"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"前の文は「利用者数が伸びている」という良い点、後の文は「利用時間が減り、収益への貢献は限定的」という逆の評価。前後が反対の内容なので、逆接の「しかし」が入る。","whatIsAskedJa":"空欄の前後の文がどのような関係（逆接・順接・言い換え・例示・追加）にあるかを判断し、それに合う接続語を選ぶ問題です。"},"itemAnalysis":{"languageLoads":["reading-comprehension"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-logic-02","version":1,"testFamily":"spi","domain":"verbal","category":"sentence-logic","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":45,"promptJa":"空欄に入る語として、最も適切なものを選びなさい。\n「当社の強みは、顧客ごとに設計を変えられる柔軟性にある。〔　　〕、標準品では対応できない要望にも応えられるということだ。」","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"しかし"},{"id":"b","textJa":"つまり"},{"id":"c","textJa":"ところで"},{"id":"d","textJa":"それでも"},{"id":"e","textJa":"ただし"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"b"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"後の文は「設計を変えられる柔軟性」を「標準品では対応できない要望にも応えられる」と具体的に言い換えている。文末の「〜ということだ」も言い換えの合図なので、「つまり」が入る。","whatIsAskedJa":"後の文が前の文を言い換えているのか、反対のことを述べているのか、話題を変えているのかを見分ける問題です。文末表現も手がかりになります。"},"itemAnalysis":{"languageLoads":["reading-comprehension"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-reading-01","version":1,"testFamily":"spi","domain":"verbal","category":"reading-inference","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"standard","targetSeconds":120,"promptJa":"次の文章を読んで、本文の内容と合致するものを選びなさい。\n\nリモートワークの普及により、オフィスの役割は「毎日作業する場所」から「対面でしかできない活動の場」へと変わりつつある。ある調査では、出社の目的として「同僚との打ち合わせ」を挙げた人が最も多く、「一人で集中して作業するため」と答えた人は少数にとどまった。こうした変化を受けて、座席数を減らす一方で、会議室や交流スペースを増やす企業も出てきている。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"調査では、一人で集中して作業するために出社する人が最も多かった。"},{"id":"b","textJa":"オフィスは、対面でしかできない活動の場としての役割を強めつつある。"},{"id":"c","textJa":"多くの企業が、会議室を減らして座席数を増やしている。"},{"id":"d","textJa":"リモートワークの普及により、オフィスは不要になった。"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"b"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"第一文に「対面でしかできない活動の場へと変わりつつある」とあり、b が合致する。a は調査結果と逆、c は座席と会議室の増減が逆、d は「不要になった」が本文にない言い過ぎ。","whatIsAskedJa":"選択肢の一つひとつを本文の該当箇所と照らし合わせ、内容の逆転や言い過ぎ（「不要になった」「多くの企業が」など）がないかを確かめる問題です。"},"itemAnalysis":{"languageLoads":["reading-comprehension"],"reasoningLoads":[],"executionLoads":["choice-elimination"]}},{"id":"spi-free-v-reading-02","version":1,"testFamily":"spi","domain":"verbal","category":"reading-inference","deliveryProfile":"web","practiceProfile":"untimed-learning","difficulty":"stretch","targetSeconds":120,"promptJa":"次の文章を読んで、本文から推論できることとして最も適切なものを選びなさい。\n\n日本企業の会議では、結論を出すことよりも、関係者の認識をそろえることが重視される場合がある。事前に関係者へ個別に説明して合意を得ておく「根回し」は、その代表的な方法である。根回しが十分であれば会議は短時間で終わるが、会議の場で初めて提案を示すと、反対意見が出て結論が持ち越されることも少なくない。","answer":{"input":{"kind":"single-choice","choices":[{"id":"a","textJa":"根回しをしておけば、会議で反対意見が出ることは決してない。"},{"id":"b","textJa":"会議の前に関係者の合意を得ておくと、会議を短く済ませやすい。"},{"id":"c","textJa":"日本企業の会議では、結論を出すことは重視されない。"},{"id":"d","textJa":"会議で初めて提案を示すほうが、結論は早く出る。"}]},"expectedAnswer":{"kind":"single-choice","choiceId":"b"},"scoring":{"kind":"exact-choice"}},"coreExplanation":{"concise":"本文の「根回しが十分であれば会議は短時間で終わる」から b が推論できる。a は「決してない」が言い過ぎ、c は本文の「場合がある」を一般化しすぎ、d は本文と逆の内容。","whatIsAskedJa":"本文に書かれていることから無理なく導ける内容を選ぶ問題です。「決して」「〜されない」のような断定は、本文の「場合がある」「少なくない」といった限定表現と比べて言い過ぎになっていないかを確認します。"},"itemAnalysis":{"languageLoads":["reading-comprehension"],"reasoningLoads":["constraint-reasoning"],"executionLoads":["choice-elimination"]}}]}}$free_spi_sample$::jsonb
);
